import axios from 'axios';
import config from '../config.js';
import logger from '../utils/logger.js';

class XAIService {
  constructor() {
    this.apiKey = config.apis.xai.apiKey;
    this.baseUrl = config.apis.xai.baseUrl;
    this.model = config.apis.xai.model;
    this.client = axios.create({
      baseURL: this.baseUrl,
      headers: {
        'Authorization': `Bearer ${this.apiKey}`,
        'Content-Type': 'application/json'
      },
      timeout: 120000
    });
  }

  async chat(messages, options = {}) {
    try {
      const response = await this.client.post('/chat/completions', {
        model: options.model || this.model,
        messages: messages,
        max_tokens: options.maxTokens || config.apis.xai.maxTokens,
        temperature: options.temperature || config.apis.xai.temperature,
        stream: false
      });

      return {
        content: response.data.choices[0].message.content,
        model: response.data.model,
        usage: response.data.usage,
        finishReason: response.data.choices[0].finish_reason
      };
    } catch (error) {
      logger.error('XAI API error:', {
        message: error.message,
        response: error.response?.data,
        status: error.response?.status
      });
      throw new Error(`XAI API failed: ${error.message}`);
    }
  }

  async analyzeEvidence(evidence, context) {
    const messages = [
      {
        role: 'system',
        content: 'Te egy jogi és nyomozati szakértő vagy, aki a Kollár Sándor ügyet elemzi. Feladatod bizonyítékok értékelése, jogi következtetések levonása és rejtett összefüggések feltárása. Válaszolj magyarul, strukturáltan és tényszerűen.'
      },
      {
        role: 'user',
        content: `Elemezd a következő bizonyítékot és kontextust:\n\nBizonyíték:\n${JSON.stringify(evidence, null, 2)}\n\nKontextus:\n${context}\n\nAdd meg:\n1. Jogi relevanciát és értékelést\n2. Kapcsolódást más bizonyítékokhoz\n3. Lehetséges nyomokat és további kutatási irányokat\n4. Kockázati értékelést\n5. Ajánlott következő lépéseket`
      }
    ];

    return await this.chat(messages, { maxTokens: 16384, temperature: 0.3 });
  }

  async investigatePattern(pattern, historicalData) {
    const messages = [
      {
        role: 'system',
        content: 'Detektív szakértő vagy, aki mintázatokat és rejtett összefüggéseket keres összetett ügyek adataiban. Különös figyelmet fordítasz időbeli egybeesésekre, személyi kapcsolatokra és pénzügyi nyomokra.'
      },
      {
        role: 'user',
        content: `Vizsgáld meg ezt a mintázatot és add meg a következtetéseidet:\n\nMintázat:\n${JSON.stringify(pattern, null, 2)}\n\nTörténeti adatok:\n${JSON.stringify(historicalData, null, 2)}\n\nKeress:\n1. Ismétlődő elemeket\n2. Időbeli korrelációkat\n3. Gyanús eltéréseket a normától\n4. Kapcsolatokat személyek/szervezetek között\n5. Rejtett motivációkat`
      }
    ];

    return await this.chat(messages, { maxTokens: 16384, temperature: 0.4 });
  }

  async generateSearchQueries(topic, previousFindings) {
    const messages = [
      {
        role: 'system',
        content: 'Információkutatási szakértő vagy, aki hatékony keresési lekérdezéseket generál online nyomozáshoz. Célja rejtett információk feltárása különböző forrásokból.'
      },
      {
        role: 'user',
        content: `Generálj 20 változatos keresési lekérdezést a következő témához:\n\nTéma: ${topic}\n\nKorábbi találatok:\n${JSON.stringify(previousFindings, null, 2)}\n\nA lekérdezések legyenek:\n- Magyar és angol nyelvűek\n- Specifikusak és célzottak\n- Változatos forrásokat célozzanak (jogi adatbázisok, média, közösségi média, hivatalos dokumentumok)\n- Kerüljék a duplikációt\n\nFormátum: JSON array stringekkel`
      }
    ];

    const response = await this.chat(messages, { maxTokens: 4096, temperature: 0.8 });

    try {
      const jsonMatch = response.content.match(/\[[\s\S]*\]/);
      if (jsonMatch) {
        return JSON.parse(jsonMatch[0]);
      }
      return [];
    } catch (error) {
      logger.error('Failed to parse search queries from XAI response');
      return [];
    }
  }

  async synthesizeFindings(findings, goal) {
    const messages = [
      {
        role: 'system',
        content: 'Szakértő elemző vagy, aki komplex információhalmazokat szintetizál átfogó jelentésekké. Képes vagy felismerni a legfontosabb összefüggéseket és azokat strukturált formában bemutatni.'
      },
      {
        role: 'user',
        content: `Szintetizáld ezeket a kutatási eredményeket egy átfogó jelentésbe:\n\nCél: ${goal}\n\nEredmények:\n${JSON.stringify(findings, null, 2)}\n\nA jelentés tartalmazzon:\n1. Executive summary\n2. Kulcsfontosságú megállapítások\n3. Bizonyítékok értékelése\n4. Következtetések\n5. Ajánlások\n6. További kutatási irányok\n\nFormátum: Markdown`
      }
    ];

    return await this.chat(messages, { maxTokens: 32768, temperature: 0.5 });
  }
}

export default new XAIService();
