import axios from 'axios';
import config from '../config.js';
import logger from '../utils/logger.js';

class GeminiService {
  constructor() {
    this.apiKey = config.apis.gemini.apiKey;
    this.baseUrl = config.apis.gemini.baseUrl;
    this.model = config.apis.gemini.model;
    this.client = axios.create({
      baseURL: this.baseUrl,
      timeout: 120000
    });
  }

  async generateContent(prompt, options = {}) {
    try {
      const response = await this.client.post(
        `/models/${this.model}:generateContent?key=${this.apiKey}`,
        {
          contents: [{
            parts: [{
              text: prompt
            }]
          }],
          generationConfig: {
            temperature: options.temperature || config.apis.gemini.temperature,
            maxOutputTokens: options.maxTokens || config.apis.gemini.maxTokens,
            topP: options.topP || 0.95,
            topK: options.topK || 40
          },
          safetySettings: [
            {
              category: 'HARM_CATEGORY_HARASSMENT',
              threshold: 'BLOCK_NONE'
            },
            {
              category: 'HARM_CATEGORY_HATE_SPEECH',
              threshold: 'BLOCK_NONE'
            },
            {
              category: 'HARM_CATEGORY_SEXUALLY_EXPLICIT',
              threshold: 'BLOCK_NONE'
            },
            {
              category: 'HARM_CATEGORY_DANGEROUS_CONTENT',
              threshold: 'BLOCK_NONE'
            }
          ]
        }
      );

      const candidate = response.data.candidates[0];
      return {
        content: candidate.content.parts[0].text,
        finishReason: candidate.finishReason,
        safetyRatings: candidate.safetyRatings,
        usage: response.data.usageMetadata
      };
    } catch (error) {
      logger.error('Gemini API error:', {
        message: error.message,
        response: error.response?.data,
        status: error.response?.status
      });
      throw new Error(`Gemini API failed: ${error.message}`);
    }
  }

  async analyzeDocument(documentText, analysisType) {
    const prompts = {
      legal: `Te egy jogi szakértő vagy. Elemezd részletesen ezt a dokumentumot jogi szempontból:\n\n${documentText}\n\nAdd meg:\n1. Jogi vonatkozások és hivatkozott jogszabályok\n2. Eljárási problémák és szabálytalanságok\n3. Releváns precedensek\n4. Jogorvoslati lehetőségek\n5. Kockázatok és következmények`,
      temporal: `Időrendi elemző szakértő vagy. Vizsgáld meg ezt a dokumentumot időbeli összefüggések szempontjából:\n\n${documentText}\n\nKeress:\n1. Dátumok és időpontok\n2. Események sorrendje\n3. Időbeli egybeesések és eltérések\n4. Határidők és késedelmek\n5. Időrendi ellentmondások`,
      factual: `Tényellenőrző szakértő vagy. Vizsgáld meg ezt a dokumentumot tények és állítások szempontjából:\n\n${documentText}\n\nEllenőrizd:\n1. Objektív tények vs. vélemények\n2. Állítások konzisztenciája\n3. Hiányzó információk\n4. Ellentmondások\n5. Ellenőrizhető adatok`,
      psychological: `Pszichológiai profiler vagy. Elemezd ezt a dokumentumot emberi viselkedés és motivációk szempontjából:\n\n${documentText}\n\nVizsgáld:\n1. Viselkedési mintázatok\n2. Motivációk és célok\n3. Stresszindikátorok\n4. Manipulációs technikák\n5. Pszichológiai nyomásgyakorlás jelei`
    };

    const prompt = prompts[analysisType] || prompts.factual;
    return await this.generateContent(prompt, { maxTokens: 8192, temperature: 0.3 });
  }

  async crossReferenceData(dataset1, dataset2, relationshipType) {
    const prompt = `Adatelemző szakértő vagy. Végezz kereszthivatkozás-elemzést két adathalmaz között:\n\nAdathalmaz 1:\n${JSON.stringify(dataset1, null, 2)}\n\nAdathalmaz 2:\n${JSON.stringify(dataset2, null, 2)}\n\nKapcsolat típusa: ${relationshipType}\n\nKeress:\n1. Egyező elemeket\n2. Kapcsolódási pontokat\n3. Eltéréseket és ellentmondásokat\n4. Rejtett összefüggéseket\n5. Mintázatokat\n\nEredmény formátuma: JSON`;

    const response = await this.generateContent(prompt, { maxTokens: 8192, temperature: 0.4 });

    try {
      const jsonMatch = response.content.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        return JSON.parse(jsonMatch[0]);
      }
      return { matches: [], connections: [], discrepancies: [] };
    } catch (error) {
      logger.error('Failed to parse cross-reference data from Gemini response');
      return { matches: [], connections: [], discrepancies: [] };
    }
  }

  async identifyAnomalies(data, baseline) {
    const prompt = `Anomália-detektáló szakértő vagy. Keress szokatlan mintázatokat és eltéréseket:\n\nVizsgált adatok:\n${JSON.stringify(data, null, 2)}\n\nAlap szint (normál):\n${JSON.stringify(baseline, null, 2)}\n\nIdentifikálj:\n1. Statisztikai outliereket\n2. Szokatlan mintázatokat\n3. Normától való eltéréseket\n4. Időbeli anomáliákat\n5. Gyanús trenddeket\n\nFormátum: JSON array anomáliaobjektumokkal (type, severity, description, evidence)`;

    const response = await this.generateContent(prompt, { maxTokens: 8192, temperature: 0.3 });

    try {
      const jsonMatch = response.content.match(/\[[\s\S]*\]/);
      if (jsonMatch) {
        return JSON.parse(jsonMatch[0]);
      }
      return [];
    } catch (error) {
      logger.error('Failed to parse anomalies from Gemini response');
      return [];
    }
  }

  async generateHypotheses(evidence, constraints) {
    const prompt = `Hipotézisgeneráló szakértő vagy. Készíts ellenőrizhető hipotéziseket a rendelkezésre álló bizonyítékok alapján:\n\nBizonyítékok:\n${JSON.stringify(evidence, null, 2)}\n\nKorlátozások:\n${JSON.stringify(constraints, null, 2)}\n\nGenerálj:\n1. Fő hipotézist\n2. Alternatív hipotéziseket (minimum 3)\n3. Minden hipotézishez: támogató bizonyítékok, cáfoló tényezők, ellenőrzési módszer\n4. Valószínűségi rangsorolás\n5. Következő vizsgálati lépések\n\nFormátum: JSON`;

    const response = await this.generateContent(prompt, { maxTokens: 8192, temperature: 0.6 });

    try {
      const jsonMatch = response.content.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        return JSON.parse(jsonMatch[0]);
      }
      return { hypotheses: [] };
    } catch (error) {
      logger.error('Failed to parse hypotheses from Gemini response');
      return { hypotheses: [] };
    }
  }
}

export default new GeminiService();
