class ExaService {
  constructor() {
    this.apiKey = config.apis.exa.apiKey;
    this.baseUrl = config.apis.exa.baseUrl;
    this.client = axios.create({
      baseURL: this.baseUrl,
      headers: {
        'x-api-key': this.apiKey,
        'Content-Type': 'application/json'
      },
      timeout: 60000
    });
  }

  async search(query, options = {}) {
    try {
      const response = await this.client.post('/search', {
        query: query,
        num_results: options.numResults || config.apis.exa.numResults,
        use_autoprompt: options.useAutoprompt !== undefined ? options.useAutoprompt : config.apis.exa.useAutoprompt,
        type: options.type || config.apis.exa.type,
        start_published_date: options.startDate,
        end_published_date: options.endDate,
        include_domains: options.includeDomains,
        exclude_domains: options.excludeDomains,
        category: options.category,
        contents: {
          text: options.getText !== false,
          highlights: options.getHighlights !== false,
          summary: options.getSummary !== false
        }
      });

      return {
        results: response.data.results,
        autopromptString: response.data.autoprompt_string,
        requestId: response.data.request_id
      };
    } catch (error) {
      logger.error('Exa API search error:', {
        message: error.message,
        response: error.response?.data,
        status: error.response?.status
      });
      throw new Error(`Exa search failed: ${error.message}`);
    }
  }

  async findSimilar(url, options = {}) {
    try {
      const response = await this.client.post('/findSimilar', {
        url: url,
        num_results: options.numResults || 20,
        start_published_date: options.startDate,
        end_published_date: options.endDate,
        exclude_source_domain: options.excludeSourceDomain !== false,
        category: options.category,
        contents: {
          text: options.getText !== false,
          highlights: options.getHighlights !== false,
          summary: options.getSummary !== false
        }
      });

      return {
        results: response.data.results,
        requestId: response.data.request_id
      };
    } catch (error) {
      logger.error('Exa API findSimilar error:', {
        message: error.message,
        response: error.response?.data,
        status: error.response?.status
      });
      throw new Error(`Exa findSimilar failed: ${error.message}`);
    }
  }

  async getContents(ids, options = {}) {
    try {
      const response = await this.client.post('/contents', {
        ids: ids,
        text: options.getText !== false,
        highlights: options.getHighlights !== false,
        summary: options.getSummary !== false
      });

      return {
        results: response.data.results,
        requestId: response.data.request_id
      };
    } catch (error) {
      logger.error('Exa API getContents error:', {
        message: error.message,
        response: error.response?.data,
        status: error.response?.status
      });
      throw new Error(`Exa getContents failed: ${error.message}`);
    }
  }

  async searchKollarCase(topic, timeRange = {}) {
    const queries = [
      `Kollár Sándor ${topic}`,
      `Szeged TEK razzia ${topic}`,
      `Készenléti Rendőrség Nemzeti Nyomozó Iroda ${topic}`,
      `dr. Lencse Balázs nyomozó ${topic}`,
      `Cédrus Liget lakópark ${topic}`,
      `gyermekpornográfia ügy Magyarország ${topic}`,
      `rendőrségi visszaélés Szeged ${topic}`,
      `jogellenes fogvatartás Magyarország ${topic}`
    ];

    const allResults = [];

    for (const query of queries) {
      try {
        const result = await this.search(query, {
          numResults: 20,
          startDate: timeRange.start,
          endDate: timeRange.end,
          includeDomains: [
            'index.hu',
            'hvg.hu',
            'telex.hu',
            '444.hu',
            'magyarnemzet.hu',
            'origo.hu',
            'portfolio.hu',
            'jogaszvilag.hu',
            'birosag.hu',
            'police.hu',
            'magyarkozlony.hu'
          ]
        });

        allResults.push({
          query: query,
          results: result.results,
          autoprompt: result.autopromptString
        });

        await new Promise(resolve => setTimeout(resolve, 500));
      } catch (error) {
        logger.warn(`Exa search failed for query: ${query}`, error);
      }
    }

    return allResults;
  }

  async deepWebSearch(keywords, options = {}) {
    const searchTypes = ['neural', 'keyword'];
    const allResults = [];

    for (const type of searchTypes) {
      try {
        const result = await this.search(keywords, {
          type: type,
          numResults: options.numResults || 30,
          startDate: options.startDate,
          endDate: options.endDate,
          excludeDomains: options.excludeDomains
        });

        allResults.push({
          searchType: type,
          results: result.results
        });

        await new Promise(resolve => setTimeout(resolve, 500));
      } catch (error) {
        logger.warn(`Exa deep search failed for type: ${type}`, error);
      }
    }

    return allResults;
  }

  async monitorNewContent(previousResults, query) {
    const latestDate = previousResults.length > 0
      ? new Date(Math.max(...previousResults.map(r => new Date(r.published_date))))
      : new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);

    const result = await this.search(query, {
      numResults: 50,
      startDate: latestDate.toISOString(),
      endDate: new Date().toISOString()
    });

    return result.results.filter(r => {
      const resultDate = new Date(r.published_date);
      return resultDate > latestDate;
    });
  }
}

export default new ExaService();
