import axios from 'axios';
import config from '../config.js';
import logger from '../utils/logger.js';

class ParallelService {
  constructor() {
    this.apiKey = config.apis.parallel.apiKey;
    this.baseUrl = config.apis.parallel.baseUrl;
    this.client = axios.create({
      baseURL: this.baseUrl,
      headers: {
        'Authorization': `Bearer ${this.apiKey}`,
        'Content-Type': 'application/json'
      },
      timeout: 90000
    });
  }

  async complete(prompt, options = {}) {
    try {
      const response = await this.client.post('/completions', {
        model: options.model || config.apis.parallel.model,
        prompt: prompt,
        max_tokens: options.maxTokens || config.apis.parallel.maxTokens,
        temperature: options.temperature || 0.7,
        top_p: options.topP || 0.9,
        frequency_penalty: options.frequencyPenalty || 0.0,
        presence_penalty: options.presencePenalty || 0.0,
        stop: options.stop
      });

      return {
        content: response.data.choices[0].text,
        model: response.data.model,
        usage: response.data.usage,
        finishReason: response.data.choices[0].finish_reason
      };
    } catch (error) {
      logger.error('Parallel API error:', {
        message: error.message,
        response: error.response?.data,
        status: error.response?.status
      });
      throw new Error(`Parallel API failed: ${error.message}`);
    }
  }

  async batch(prompts, options = {}) {
    try {
      const response = await this.client.post('/batch', {
        model: options.model || config.apis.parallel.model,
        requests: prompts.map(prompt => ({
          prompt: prompt,
          max_tokens: options.maxTokens || config.apis.parallel.maxTokens,
          temperature: options.temperature || 0.7
        }))
      });

      return response.data.results.map(result => ({
        content: result.choices[0].text,
        usage: result.usage
      }));
    } catch (error) {
      logger.error('Parallel batch API error:', {
        message: error.message,
        response: error.response?.data,
        status: error.response?.status
      });
      throw new Error(`Parallel batch API failed: ${error.message}`);
    }
  }

  async analyzeMultipleSources(sources) {
    const prompts = sources.map(source => 
      `Elemezd ezt a forrást a Kollár Sándor ügy kontextusában:\n\nForrás: ${source.title}\nURL: ${source.url}\nTartalom: ${source.content}\n\nAdd meg:\n1. Relevanciát (0-10)\n2. Kulcsinformációk\n3. Hivatkozott személyek/szervezetek\n4. Időpontok\n5. Kapcsolódási pontok más forrásokhoz`
    );

    return await this.batch(prompts, { maxTokens: 2048, temperature: 0.3 });
  }

  async extractEntities(text) {
    const prompt = `Entitásfelismerő rendszer vagy. Azonosítsd és kategorizáld az összes releváns entitást ebben a szövegben:\n\n${text}\n\nKategóriák:\n- PERSON (személyek)\n- ORGANIZATION (szervezetek)\n- LOCATION (helyszínek)\n- DATE (dátumok)\n- EVENT (események)\n- LEGAL_REFERENCE (jogi hivatkozások)\n- DOCUMENT (dokumentumok)\n\nFormátum: JSON array objektumokkal (entity, category, context)`;

    const response = await this.complete(prompt, { maxTokens: 4096, temperature: 0.1 });

    try {
      const jsonMatch = response.content.match(/\[[\s\S]*\]/);
      if (jsonMatch) {
        return JSON.parse(jsonMatch[0]);
      }
      return [];
    } catch (error) {
      logger.error('Failed to parse entities from Parallel response');
      return [];
    }
  }

  async compareVersions(version1, version2) {
    const prompt = `Dokumentum-összehasonlító szakértő vagy. Hasonlítsd össze ezt a két verziót és jelöld a különbségeket:\n\nVerzió 1:\n${version1}\n\nVerzió 2:\n${version2}\n\nIdentifikálj:\n1. Hozzáadott részek\n2. Törölt részek\n3. Módosított részek\n4. Átfogalmazások\n5. Jelentésmódosítások\n\nFormátum: strukturált szöveges jelentés`;

    return await this.complete(prompt, { maxTokens: 4096, temperature: 0.2 });
  }

  async summarizeTimeline(events) {
    const prompt = `Időrendelést készítő szakértő vagy. Fogladd össze ezeket az eseményeket kronológiai sorrendben:\n\nEsemények:\n${JSON.stringify(events, null, 2)}\n\nKészíts:\n1. Kronológiai összefoglalót\n2. Fázisokat (pl. előkészítés, végrehajtás, utóhatások)\n3. Fordulópontokat\n4. Kapcsolódó események csoportosítását\n5. Hiányzó időszakok jelzését\n\nFormátum: Markdown timeline`;

    return await this.complete(prompt, { maxTokens: 4096, temperature: 0.4 });
  }
}

export default new ParallelService();
