  async saveSearchResult(result) {
    try {
      const docRef = this.db.collection('search_results').doc();
      await docRef.set({
        ...result,
        createdAt: Firestore.FieldValue.serverTimestamp(),
        updatedAt: Firestore.FieldValue.serverTimestamp()
