  async batchSave(collection, documents) {
    try {
      const batch = this.db.batch();

      documents.forEach(doc => {
        const docRef = this.db.collection(collection).doc();
        batch.set(docRef, {
          ...doc,
          createdAt: Firestore.FieldValue.serverTimestamp()
        });
      });

      await batch.commit();
    } catch (error) {
      logger.error(`Error batch saving to ${collection}:`, error);
      throw error;
    }
  }

  async cleanOldData(collection, daysToKeep) {
    try {
      const cutoffDate = new Date();
      cutoffDate.setDate(cutoffDate.getDate() - daysToKeep);

      const snapshot = await this.db.collection(collection)
        .where('createdAt', '<', cutoffDate)
        .get();

      const batch = this.db.batch();
      snapshot.docs.forEach(doc => {
        batch.delete(doc.ref);
      });

      await batch.commit();
      logger.info(`Cleaned ${snapshot.size} old documents from ${collection}`);
    } catch (error) {
      logger.error(`Error cleaning old data from ${collection}:`, error);
      throw error;
    }
  }
}

export default new FirestoreService();
