```javascript
import xaiService from './xai.service.js';
import geminiService from './gemini.service.js';
import exaService from './exa.service.js';
import parallelService from './parallel.service.js';
import firestoreService from './firestore.service.js';
import logger from '../utils/logger.js';
import { generateSearchQueries, analyzeRelevance } from '../utils/search-queries.js';
import config from '../config.js';

class InvestigationService {
  constructor() {
    this.isRunning = false;
    this.lastRunTimestamp = null;
    this.runCount = 0;
  }

  async executeFullInvestigationCycle() {
    if (this.isRunning) {
      logger.warn('Investigation cycle already running, skipping...');
      return;
    }

    this.isRunning = true;
    this.runCount++;
    const startTime = Date.now();

    logger.info(`Starting investigation cycle #${this.runCount}`);

    try {
      await firestoreService.saveInvestigationLog({
        cycleNumber: this.runCount,
        status: 'started',
        message: 'Investigation cycle initiated'
      });

      const previousFindings = await firestoreService.getSearchResults({ relevanceMin: 0.7 }, 50);

      const searchQueries = await this.generateDynamicSearchQueries(previousFindings);

      const searchResults = await this.performMultiSourceSearch(searchQueries);

      const analyzedResults = await this.analyzeSearchResults(searchResults);

      const highValueResults = analyzedResults.filter(r => r.relevance >= config.investigation.alertThreshold);

      if (highValueResults.length > 0) {
        await this.processHighValueFindings(highValueResults);
      }

      const crossReferences = await this.performCrossReferenceAnalysis(analyzedResults);

      const anomalies = await this.detectAnomalies(analyzedResults);

      const patterns = await this.identifyPatterns(analyzedResults);

      const report = await this.generateCycleReport({
        cycleNumber: this.runCount,
        queriesExecuted: searchQueries.length,
        resultsFound: searchResults.length,
        highValueFindings: highValueResults.length,
        crossReferences: crossReferences,
        anomalies: anomalies,
        patterns: patterns,
        duration: Date.now() - startTime
      });

      await firestoreService.saveAnalysis({
        type: 'cycle_report',
        cycleNumber: this.runCount,
        report: report,
        metrics: {
          duration: Date.now() - startTime,
          queriesExecuted: searchQueries.length,
          resultsFound: searchResults.length,
          highValueFindings: highValueResults.length
        }
      });

      await firestoreService.saveInvestigationLog({
        cycleNumber: this.runCount,
        status: 'completed',
        message: 'Investigation cycle completed successfully',
        duration: Date.now() - startTime
      });

      this.lastRunTimestamp = Date.now();
      logger.info(`Investigation cycle #${this.runCount} completed in ${Date.now() - startTime}ms`);

    } catch (error) {
      logger.error('Investigation cycle failed:', error);

      await firestoreService.saveInvestigationLog({
        cycleNumber: this.runCount,
        status: 'failed',
        error: error.message,
        stack: error.stack
      });

      await firestoreService.saveAlert({
        type: 'system_error',
        severity: 'high',
        title: 'Investigation Cycle Failed',
        message: `Cycle #${this.runCount} failed: ${error.message}`,
        metadata: { cycleNumber: this.runCount, error: error.stack }
      });

    } finally {
      this.isRunning = false;
    }
  }

  async generateDynamicSearchQueries(previousFindings) {
    const baseTopics = [
      'Kollár Sándor rendőrségi eljárás',
      'TEK bevetés Szeged 2025 március',
      'dr. Lencse Balázs nyomozó',
      'Cédrus Liget lakópark razzia',
      'jogellenes fogvatartás Magyarország',
      'rendőrségi visszaélés Szeged',
      'Készenléti Rendőrség Nemzeti Nyomozó Iroda',
      'M. Zoltán tanú elővezetés',
      'Balatonfűzfő garázdaság 2024',
      'kábítószer csekély mennyiség ügy'
    ];

    const allQueries = [...generateSearchQueries()];

    for (const topic of baseTopics) {
      try {
        const aiGeneratedQueries = await xaiService.generateSearchQueries(topic, previousFindings);
        allQueries.push(...aiGeneratedQueries);
      } catch (error) {
        logger.warn(`Failed to generate AI queries for topic: ${topic}`, error);
      }
    }

    return [...new Set(allQueries)];
  }

  async performMultiSourceSearch(queries) {
    const allResults = [];
    const batchSize = config.investigation.maxConcurrentSearches;

    for (let i = 0; i < queries.length; i += batchSize) {
      const batch = queries.slice(i, i + batchSize);

      const batchPromises = batch.map(async (query) => {
        try {
          const exaResults = await exaService.search(query, {
            numResults: 20,
            includeDomains: [
              'index.hu', 'hvg.hu', 'telex.hu', '444.hu',
              'magyarnemzet.hu', 'origo.hu', 'portfolio.hu',
              'jogaszvilag.hu', 'birosag.hu', 'police.hu'
            ]
          });

          return exaResults.results.map(r => ({
            ...r,
            query: query,
            source: 'exa',
            timestamp: new Date().toISOString()
          }));
        } catch (error) {
          logger.warn(`Search failed for query: ${query}`, error);
          return [];
        }
      });

      const batchResults = await Promise.all(batchPromises);
      allResults.push(...batchResults.flat());

      await new Promise(resolve => setTimeout(resolve, 1000));
    }

    for (const result of allResults) {
      await firestoreService.saveSearchResult(result);
    }

    return allResults;
  }

  async analyzeSearchResults(results) {
    const analyzed = [];

    for (const result of results) {
      try {
        const xaiAnalysis = await xaiService.analyzeEvidence(result, 'Kollár Sándor ügy kontextusában értékeld ezt a találatot');

        const geminiAnalysis = await geminiService.analyzeDocument(result.text || result.summary || '', 'factual');

        const parallelEntities = await parallelService.extractEntities(result.text || result.summary || '');

        const relevance = analyzeRelevance(result);

        const analyzedResult = {
          ...result,
          analysis: {
            xai: xaiAnalysis.content,
            gemini: geminiAnalysis.content,
            entities: parallelEntities
          },
          relevance: relevance,
          analyzedAt: new Date().toISOString()
        };

        analyzed.push(analyzedResult);

        await firestoreService.saveEvidence({
          type: 'search_result',
          source: result.source,
          url: result.url,
          title: result.title,
          content: result.text || result.summary,
          analysis: analyzedResult.analysis,
          relevance: relevance,
          metadata: result
        });

      } catch (error) {
        logger.warn(`Failed to analyze result: ${result.url}`, error);
        analyzed.push({ ...result, relevance: 0 });
      }
    }

    return analyzed;
  }

  async processHighValueFindings(findings) {
    for (const finding of findings) {
      await firestoreService.saveAlert({
        type: 'high_value_finding',
        severity: 'high',
        title: `Új releváns információ: ${finding.title}`,
        message: `Magas relevanciájú találat (${(finding.relevance * 100).toFixed(1)}%)`,
        url: finding.url,
        metadata: finding
      });

      try {
        const similarContent = await exaService.findSimilar(finding.url, { numResults: 10 });

        for (const similar of similarContent.results) {
          await firestoreService.saveSearchResult({
            ...similar,
            source: 'exa_similar',
            relatedTo: finding.url,
            timestamp: new Date().toISOString()
          });
        }
      } catch (error) {
        logger.warn(`Failed to find similar content for: ${finding.url}`, error);
      }
    }
  }

  async performCrossReferenceAnalysis(results) {
    const entities = results.flatMap(r => r.analysis?.entities || []);
    const personEntities = entities.filter(e => e.category === 'PERSON');
    const orgEntities = entities.filter(e => e.category === 'ORGANIZATION');

    const crossRefs = {
      persons: this.groupByEntity(personEntities),
      organizations: this.groupByEntity(orgEntities)
    };

    try {
      const geminiCrossRef = await geminiService.crossReferenceData(
        crossRefs.persons,
        crossRefs.organizations,
        'investigation_connections'
      );

      await firestoreService.saveAnalysis({
        type: 'cross_reference',
        aiModel: 'gemini',
        data: geminiCrossRef
      });

      return geminiCrossRef;
    } catch (error) {
      logger.error('Cross-reference analysis failed:', error);
      return crossRefs;
    }
  }

  async detectAnomalies(results) {
    const recentResults = results.slice(0, 50);
    const historicalResults = await firestoreService.getSearchResults({
      startDate: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString()
    }, 200);

    try {
      const anomalies = await geminiService.identifyAnomalies(recentResults, historicalResults);

      for (const anomaly of anomalies) {
        if (anomaly.severity === 'high' || anomaly.severity === 'critical') {
          await firestoreService.saveAlert({
            type: 'anomaly_detected',
            severity: anomaly.severity,
            title: `Anomália észlelve: ${anomaly.type}`,
            message: anomaly.description,
            metadata: anomaly
          });
        }
      }

      await firestoreService.saveAnalysis({
        type: 'anomaly_detection',
        aiModel: 'gemini',
        anomalies: anomalies
      });

      return anomalies;
    } catch (error) {
      logger.error('Anomaly detection failed:', error);
      return [];
    }
  }

  async identifyPatterns(results) {
    const temporalData = results.map(r => ({
      date: r.published_date || r.timestamp,
      entities: r.analysis?.entities || [],
      relevance: r.relevance
    }));

    try {
      const patternAnalysis = await xaiService.investigatePattern(
        { temporal: temporalData },
        { previousCycles: this.runCount }
      );

      await firestoreService.saveAnalysis({
        type: 'pattern_identification',
        aiModel: 'xai',
        patterns: patternAnalysis.content
      });

      return patternAnalysis.content;
    } catch (error) {
      logger.error('Pattern identification failed:', error);
      return null;
    }
  }

  async generateCycleReport(metrics) {
    try {
      const allEvidence = await firestoreService.getEvidence({}, 100);
      const allAlerts = await firestoreService.getUnreadAlerts(50);

      const report = await xaiService.synthesizeFindings(
        {
          metrics: metrics,
          evidence: allEvidence,
          alerts: allAlerts
        },
        'Átfogó jelentés készítése a legfrissebb kutatási ciklusról'
      );

      return report.content;
    } catch (error) {
      logger.error('Report generation failed:', error);
      return `Cycle #${metrics.cycleNumber} completed with ${metrics.resultsFound} results.`;
    }
  }

  groupByEntity(entities) {
    const grouped = {};
    for (const entity of entities) {
      const key = entity.entity.toLowerCase().trim();
      if (!grouped[key]) {
        grouped[key] = [];
      }
      grouped[key].push(entity);
    }
    return grouped;
  }

  async getStatus() {
    return {
      isRunning: this.isRunning,
      lastRun: this.lastRunTimestamp ? new Date(this.lastRunTimestamp).toISOString() : null,
      runCount: this.runCount,
      nextRunEstimate: this.lastRunTimestamp 
        ? new Date(this.lastRunTimestamp + config.investigation.searchInterval).toISOString()
        : 'soon'
    };
  }
}

export default new InvestigationService();
