import express from 'express';
import investigationService from '../services/investigation.service.js';
import firestoreService from '../services/firestore.service.js';
import logger from '../utils/logger.js';

const router = express.Router();

router.post('/trigger', async (req, res, next) => {
  try {
    if (investigationService.isRunning) {
      return res.status(409).json({
        success: false,
        message: 'Investigation cycle is already running'
      });
    }

    investigationService.executeFullInvestigationCycle().catch(err => {
      logger.error('Background investigation failed:', err);
    });

    res.json({
      success: true,
      message: 'Investigation cycle triggered',
      status: await investigationService.getStatus()
    });
  } catch (error) {
    next(error);
  }
});

router.get('/status', async (req, res, next) => {
  try {
    const status = await investigationService.getStatus();
    res.json({ success: true, data: status });
  } catch (error) {
    next(error);
  }
});

router.get('/report/latest', async (req, res, next) => {
  try {
    const analyses = await firestoreService.getAnalyses({ type: 'cycle_report' }, 1);

    if (analyses.length === 0) {
      return res.status(404).json({
        success: false,
        message: 'No reports found'
      });
    }

    res.json({ success: true, data: analyses[0] });
  } catch (error) {
    next(error);
  }
});

router.get('/report/history', async (req, res, next) => {
  try {
    const limit = parseInt(req.query.limit || '10', 10);
    const analyses = await firestoreService.getAnalyses({ type: 'cycle_report' }, limit);
    res.json({ success: true, data: analyses, count: analyses.length });
  } catch (error) {
    next(error);
  }
});

router.get('/statistics', async (req, res, next) => {
  try {
    const startDate = req.query.startDate || new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();
    const endDate = req.query.endDate || new Date().toISOString();

    const [searchResults, evidence, analyses, alerts, logs] = await Promise.all([
      firestoreService.getSearchResults({ startDate, endDate }, 10000),
      firestoreService.getEvidence({}, 10000),
      firestoreService.getAnalyses({}, 1000),
      firestoreService.getUnreadAlerts(1000),
      firestoreService.getInvestigationLogs({ startDate, endDate }, 1000)
    ]);

    const highValueEvidence = evidence.filter(e => e.relevance >= 0.7);
    const criticalAlerts = alerts.filter(a => a.severity === 'high' || a.severity === 'critical');

    const statistics = {
      period: { startDate, endDate },
      totals: {
        searchResults: searchResults.length,
        evidence: evidence.length,
        highValueEvidence: highValueEvidence.length,
        analyses: analyses.length,
        alerts: alerts.length,
        criticalAlerts: criticalAlerts.length,
        investigationCycles: logs.filter(l => l.status === 'completed').length
      },
      averageRelevance: evidence.length > 0
        ? evidence.reduce((sum, e) => sum + (e.relevance || 0), 0) / evidence.length
        : 0,
      successRate: logs.length > 0
        ? logs.filter(l => l.status === 'completed').length / logs.length
        : 0
    };

    res.json({ success: true, data: statistics });
  } catch (error) {
    next(error);
  }
});

router.post('/search/custom', async (req, res, next) => {
  try {
    const { queries } = req.body;

    if (!Array.isArray(queries) || queries.length === 0) {
      return res.status(400).json({
        success: false,
        message: 'Queries array is required'
      });
    }

    const results = [];

    for (const query of queries) {
      try {
        const searchResult = await investigationService.performMultiSourceSearch([query]);
        results.push(...searchResult);
      } catch (error) {
        logger.warn(`Custom search failed for query: ${query}`, error);
      }
    }

    res.json({
      success: true,
      data: results,
      count: results.length
    });
  } catch (error) {
    next(error);
  }
});

export default router;
