import config from '../config.js';
import logger from '../utils/logger.js';

const authMiddleware = (req, res, next) => {
  const apiKey = req.header('X-API-Key') || req.query.apiKey;
  const authHeader = req.header('Authorization');

  if (!apiKey && !authHeader) {
    return res.status(401).json({
      success: false,
      error: 'Authentication required',
      message: 'Provide X-API-Key header or Authorization bearer token'
    });
  }

  if (apiKey) {
    if (config.auth.apiKeys.length === 0 || config.auth.apiKeys.includes(apiKey)) {
      req.auth = { type: 'api_key', validated: true };
      return next();
    } else {
      return res.status(403).json({
        success: false,
        error: 'Invalid API key'
      });
    }
  }

  if (authHeader && authHeader.startsWith('Bearer ')) {
    const token = authHeader.substring(7);

    if (config.auth.apiKeys.length === 0 || config.auth.apiKeys.includes(token)) {
      req.auth = { type: 'bearer', validated: true };
      return next();
    } else {
      return res.status(403).json({
        success: false,
        error: 'Invalid bearer token'
      });
    }
  }

  return res.status(401).json({
    success: false,
    error: 'Invalid authentication format'
  });
};

export default authMiddleware;
