import cron from 'node-cron';
import investigationService from '../services/investigation.service.js';
import firestoreService from '../services/firestore.service.js';
import config from '../config.js';
import logger from '../utils/logger.js';

let cronJob = null;

export function startContinuousResearch() {
  const intervalMinutes = config.investigation.searchInterval / 60000;

  const cronExpression = `*/${intervalMinutes} * * * *`;

  if (cronJob) {
    cronJob.stop();
  }

  cronJob = cron.schedule(cronExpression, async () => {
    logger.info('Scheduled investigation cycle triggered');
    try {
      await investigationService.executeFullInvestigationCycle();
    } catch (error) {
      logger.error('Scheduled investigation cycle failed:', error);
    }
  }, {
    scheduled: true,
    timezone: 'Europe/Budapest'
  });

  logger.info(`Continuous research started with interval: ${intervalMinutes} minutes`);

  setTimeout(async () => {
    logger.info('Executing initial investigation cycle');
    try {
      await investigationService.executeFullInvestigationCycle();
    } catch (error) {
      logger.error('Initial investigation cycle failed:', error);
    }
  }, 5000);

  const deepScanExpression = '0 */6 * * *';

  cron.schedule(deepScanExpression, async () => {
    logger.info('Deep scan triggered');
    try {
      const retentionDays = config.investigation.retentionDays;
      await firestoreService.cleanOldData('search_results', retentionDays);
      await firestoreService.cleanOldData('investigation_logs', retentionDays);
      logger.info('Deep scan completed');
    } catch (error) {
      logger.error('Deep scan failed:', error);
    }
  }, {
    scheduled: true,
    timezone: 'Europe/Budapest'
  });
}

export function stopContinuousResearch() {
  if (cronJob) {
    cronJob.stop();
    cronJob = null;
    logger.info('Continuous research stopped');
  }
}
