export function analyzeRelevance(result) {
  const keywords = [
    'kollár', 'sándor', 'tek', 'razzia', 'szeged', 'lencse', 'balázs',
    'cédrus', 'liget', 'zoltán', 'jogellenes', 'fogvatartás',
    'visszaélés', 'rendőrség', 'balatonfűzfő', 'gyermekpornográfia',
    'kábítószer', 'csekély', 'mennyiség', 'házkutatás', 'terrorelhárítás',
    'zombi', 'ügy', 'védőkirendelés', 'europol', 'stream', 'zersetzung',
    'megfigyelés', 'gps', 'nyomkövetés', 'behatolás', 'anpr',
    'zaklatás', 'ejeb', 'helsinki', 'tasz', 'btk', '304', '305', 'rtv'
  ];

  const text = `${result.title} ${result.text || result.summary || ''}`.toLowerCase();

  let relevanceScore = 0;
  let matchedKeywords = 0;

  for (const keyword of keywords) {
    if (text.includes(keyword)) {
      matchedKeywords++;
      relevanceScore += 0.02;
    }
  }

  if (result.published_date || result.timestamp) {
    const date = new Date(result.published_date || result.timestamp);
    const daysSince = (Date.now() - date.getTime()) / (1000 * 60 * 60 * 24);

    if (daysSince < 7) {
      relevanceScore += 0.2;
    } else if (daysSince < 30) {
      relevanceScore += 0.1;
    } else if (daysSince < 90) {
      relevanceScore += 0.05;
    }
  }

  if (result.domain) {
    const trustDomains = ['hvg.hu', 'telex.hu', '444.hu', 'index.hu', 'birosag.hu', 'police.hu'];
    if (trustDomains.some(d => result.domain.includes(d))) {
      relevanceScore += 0.1;
    }
  }

  return Math.min(relevanceScore, 1.0);
}
