from typing import Dict, Any, List, Optional
from datetime import datetime, timedelta
import asyncio
from services.xai_service import xai_service
from services.gemini_service import gemini_service
from services.exa_service import exa_service
from services.parallel_service import parallel_service
from services.firestore_service import firestore_service
from utils.logger import logger
from utils.search_queries import generate_search_queries, analyze_relevance
from config import settings

class InvestigationService:
    def __init__(self):
        self.is_running = False
        self.last_run_timestamp = None
        self.run_count = 0

    async def execute_full_investigation_cycle(self):
        if self.is_running:
            logger.warning("Investigation cycle already running, skipping...")
            return

        self.is_running = True
        self.run_count += 1
        start_time = datetime.now()

        logger.info(f"Starting investigation cycle #{self.run_count}")

        try:
            await firestore_service.save_investigation_log({
                "cycle_number": self.run_count,
                "status": "started",
                "message": "Investigation cycle initiated"
            })

            previous_findings = await firestore_service.get_search_results(
                {"relevance_min": 0.7},
                50
            )

            search_queries = await self.generate_dynamic_search_queries(previous_findings)

            search_results = await self.perform_multi_source_search(search_queries)

            analyzed_results = await self.analyze_search_results(search_results)

            high_value_results = [r for r in analyzed_results if r.get("relevance", 0) >= settings.ALERT_THRESHOLD]

            if high_value_results:
                await self.process_high_value_findings(high_value_results)

            cross_references = await self.perform_cross_reference_analysis(analyzed_results)

            anomalies = await self.detect_anomalies(analyzed_results)

            patterns = await self.identify_patterns(analyzed_results)

            duration = (datetime.now() - start_time).total_seconds()

            report = await self.generate_cycle_report({
                "cycle_number": self.run_count,
                "queries_executed": len(search_queries),
                "results_found": len(search_results),
                "high_value_findings": len(high_value_results),
                "cross_references": cross_references,
                "anomalies": anomalies,
                "patterns": patterns,
                "duration": duration
            })

            await firestore_service.save_analysis({
                "type": "cycle_report",
                "cycle_number": self.run_count,
                "report": report,
                "metrics": {
                    "duration": duration,
                    "queries_executed": len(search_queries),
                    "results_found": len(search_results),
                    "high_value_findings": len(high_value_results)
                }
            })

            await firestore_service.save_investigation_log({
                "cycle_number": self.run_count,
                "status": "completed",
                "message": "Investigation cycle completed successfully",
                "duration": duration
            })

            self.last_run_timestamp = datetime.now()
            logger.info(f"Investigation cycle #{self.run_count} completed in {duration}s")

        except Exception as e:
            logger.error(f"Investigation cycle failed: {str(e)}")

            await firestore_service.save_investigation_log({
                "cycle_number": self.run_count,
                "status": "failed",
                "error": str(e)
            })

            await firestore_service.save_alert({
                "type": "system_error",
                "severity": "high",
                "title": "Investigation Cycle Failed",
                "message": f"Cycle #{self.run_count} failed: {str(e)}",
                "metadata": {"cycle_number": self.run_count}
            })

        finally:
            self.is_running = False

    async def generate_dynamic_search_queries(self, previous_findings: List[Dict[str, Any]]) -> List[str]:
        base_topics = [
            "Kollár Sándor rendőrségi eljárás",
            "TEK bevetés Szeged 2025 március",
            "dr. Lencse Balázs nyomozó",
            "Cédrus Liget lakópark razzia",
            "jogellenes fogvatartás Magyarország",
            "rendőrségi visszaélés Szeged",
            "Készenléti Rendőrség Nemzeti Nyomozó Iroda",
            "M. Zoltán tanú elővezetés",
            "Balatonfűzfő garázdaság 2024",
            "kábítószer csekély mennyiség ügy"
        ]

        all_queries = list(generate_search_queries())

        for topic in base_topics:
            try:
                ai_generated_queries = await xai_service.generate_search_queries(topic, previous_findings)
                all_queries.extend(ai_generated_queries)
            except Exception as e:
                logger.warning(f"Failed to generate AI queries for topic: {topic}, error: {str(e)}")

        return list(set(all_queries))

    async def perform_multi_source_search(self, queries: List[str]) -> List[Dict[str, Any]]:
        all_results = []
        batch_size = settings.MAX_CONCURRENT_SEARCHES

        for i in range(0, len(queries), batch_size):
            batch = queries[i:i + batch_size]

            tasks = []
            for query in batch:
                tasks.append(self._search_single_query(query))

            batch_results = await asyncio.gather(*tasks, return_exceptions=True)

            for result in batch_results:
                if isinstance(result, Exception):
                    logger.warning(f"Search task failed: {str(result)}")
                elif result:
                    all_results.extend(result)

            await asyncio.sleep(1)

        for result in all_results:
            await firestore_service.save_search_result(result)

        return all_results

    async def _search_single_query(self, query: str) -> List[Dict[str, Any]]:
        try:
            exa_results = await exa_service.search(query, {
                "num_results": 20,
                "include_domains": [
                    "index.hu", "hvg.hu", "telex.hu", "444.hu",
                    "magyarnemzet.hu", "origo.hu", "portfolio.hu",
                    "jogaszvilag.hu", "birosag.hu", "police.hu"
                ]
            })

            return [
                {
                    **r,
                    "query": query,
                    "source": "exa",
                    "timestamp": datetime.now().isoformat()
                }
                for r in exa_results["results"]
            ]
        except Exception as e:
            logger.warning(f"Search failed for query: {query}, error: {str(e)}")
            return []

    async def analyze_search_results(self, results: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        analyzed = []

        for result in results:
            try:
                xai_analysis = await xai_service.analyze_evidence(
                    result,
                    "Kollár Sándor ügy kontextusában értékeld ezt a találatot"
                )

                gemini_analysis = await gemini_service.analyze_document(
                    result.get("text") or result.get("summary") or "",
                    "factual"
                )

                parallel_entities = await parallel_service.extract_entities(
                    result.get("text") or result.get("summary") or ""
                )

                relevance = analyze_relevance(result)

                analyzed_result = {
                    **result,
                    "analysis": {
                        "xai": xai_analysis["content"],
                        "gemini": gemini_analysis["content"],
                        "entities": parallel_entities
                    },
                    "relevance": relevance,
                    "analyzed_at": datetime.now().isoformat()
                }

                analyzed.append(analyzed_result)

                await firestore_service.save_evidence({
                    "type": "search_result",
                    "source": result.get("source"),
                    "url": result.get("url"),
                    "title": result.get("title"),
                    "content": result.get("text") or result.get("summary"),
                    "analysis": analyzed_result["analysis"],
                    "relevance": relevance,
                    "metadata": result
                })

            except Exception as e:
                logger.warning(f"Failed to analyze result: {result.get('url')}, error: {str(e)}")
                analyzed.append({**result, "relevance": 0})

        return analyzed

    async def process_high_value_findings(self, findings: List[Dict[str, Any]]):
        for finding in findings:
            await firestore_service.save_alert({
                "type": "high_value_finding",
                "severity": "high",
                "title": f"Új releváns információ: {finding.get('title')}",
                "message": f"Magas relevanciájú találat ({finding.get('relevance', 0) * 100:.1f}%)",
                "url": finding.get("url"),
                "metadata": finding
            })

            try:
                similar_content = await exa_service.find_similar(finding["url"], {"num_results": 10})

                for similar in similar_content["results"]:
                    await firestore_service.save_search_result({
                        **similar,
                        "source": "exa_similar",
                        "related_to": finding["url"],
                        "timestamp": datetime.now().isoformat()
                    })
            except Exception as e:
                logger.warning(f"Failed to find similar content for: {finding.get('url')}, error: {str(e)}")

    async def perform_cross_reference_analysis(self, results: List[Dict[str, Any]]) -> Dict[str, Any]:
        entities = []
        for r in results:
            entities.extend(r.get("analysis", {}).get("entities", []))

        person_entities = [e for e in entities if e.get("category") == "PERSON"]
        org_entities = [e for e in entities if e.get("category") == "ORGANIZATION"]

        cross_refs = {
            "persons": self._group_by_entity(person_entities),
            "organizations": self._group_by_entity(org_entities)
        }

        try:
            gemini_cross_ref = await gemini_service.cross_reference_data(
                cross_refs["persons"],
                cross_refs["organizations"],
                "investigation_connections"
            )

            await firestore_service.save_analysis({
                "type": "cross_reference",
                "ai_model": "gemini",
                "data": gemini_cross_ref
            })

            return gemini_cross_ref
        except Exception as e:
            logger.error(f"Cross-reference analysis failed: {str(e)}")
            return cross_refs

    async def detect_anomalies(self, results: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        recent_results = results[:50]

        start_date = (datetime.now() - timedelta(days=30)).isoformat()
        historical_results = await firestore_service.get_search_results(
            {"start_date": start_date},
            200
        )

        try:
            anomalies = await gemini_service.identify_anomalies(recent_results, historical_results)

            for anomaly in anomalies:
                if anomaly.get("severity") in ["high", "critical"]:
                    await firestore_service.save_alert({
                        "type": "anomaly_detected",
                        "severity": anomaly["severity"],
                        "title": f"Anomália észlelve: {anomaly.get('type')}",
                        "message": anomaly.get("description"),
                        "metadata": anomaly
                    })

            await firestore_service.save_analysis({
                "type": "anomaly_detection",
                "ai_model": "gemini",
                "anomalies": anomalies
            })

            return anomalies
        except Exception as e:
            logger.error(f"Anomaly detection failed: {str(e)}")
            return []

    async def identify_patterns(self, results: List[Dict[str, Any]]) -> Optional[str]:
        temporal_data = [
            {
                "date": r.get("published_date") or r.get("timestamp"),
                "entities": r.get("analysis", {}).get("entities", []),
                "relevance": r.get("relevance")
            }
            for r in results
        ]

        try:
            pattern_analysis = await xai_service.investigate_pattern(
                {"temporal": temporal_data},
                {"previous_cycles": self.run_count}
            )

            await firestore_service.save_analysis({
                "type": "pattern_identification",
                "ai_model": "xai",
                "patterns": pattern_analysis["content"]
            })

            return pattern_analysis["content"]
        except Exception as e:
            logger.error(f"Pattern identification failed: {str(e)}")
            return None

    async def generate_cycle_report(self, metrics: Dict[str, Any]) -> str:
        try:
            all_evidence = await firestore_service.get_evidence({}, 100)
            all_alerts = await firestore_service.get_unread_alerts(50)

            report = await xai_service.synthesize_findings(
                {
                    "metrics": metrics,
                    "evidence": all_evidence,
                    "alerts": all_alerts
                },
                "Átfogó jelentés készítése a legfrissebb kutatási ciklusról"
            )

            return report["content"]
        except Exception as e:
            logger.error(f"Report generation failed: {str(e)}")
            return f"Cycle #{metrics['cycle_number']} completed with {metrics['results_found']} results."

    def _group_by_entity(self, entities: List[Dict[str, Any]]) -> Dict[str, List[Dict[str, Any]]]:
        grouped = {}
        for entity in entities:
            key = entity.get("entity", "").lower().strip()
            if key:
                if key not in grouped:
                    grouped[key] = []
                grouped[key].append(entity)
        return grouped

    async def get_status(self) -> Dict[str, Any]:
        next_run = None
        if self.last_run_timestamp:
            next_run_time = self.last_run_timestamp + timedelta(minutes=settings.SEARCH_INTERVAL_MINUTES)
            next_run = next_run_time.isoformat()

        return {
            "is_running": self.is_running,
            "last_run": self.last_run_timestamp.isoformat() if self.last_run_timestamp else None,
            "run_count": self.run_count,
            "next_run_estimate": next_run or "soon"
        }

investigation_service = InvestigationService()
