from fastapi import APIRouter, Depends, HTTPException, Query, BackgroundTasks
from typing import Optional, List
from pydantic import BaseModel
from datetime import datetime, timedelta
from services.investigation_service import investigation_service
from services.firestore_service import firestore_service
from middleware.auth_middleware import verify_api_key
from utils.logger import logger

router = APIRouter(dependencies=[Depends(verify_api_key)])

class CustomSearchRequest(BaseModel):
    queries: List[str]

@router.post("/trigger")
async def trigger_investigation(background_tasks: BackgroundTasks):
    try:
        if investigation_service.is_running:
            raise HTTPException(status_code=409, detail="Investigation cycle is already running")

        background_tasks.add_task(investigation_service.execute_full_investigation_cycle)

        status = await investigation_service.get_status()
        return {
            "success": True,
            "message": "Investigation cycle triggered",
            "status": status
        }
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Trigger investigation failed: {str(e)}")
        raise HTTPException(status_code=500, detail=str(e))

