@router.get("/statistics")
async def get_statistics(
    start_date: Optional[str] = Query(None),
    end_date: Optional[str] = Query(None)
):
    try:
        if not start_date:
            start_date = (datetime.now() - timedelta(days=7)).isoformat()
        if not end_date:
            end_date = datetime.now().isoformat()

        search_results = await firestore_service.get_search_results(
            {"start_date": start_date, "end_date": end_date},
            10000
        )
        evidence = await firestore_service.get_evidence({}, 10000)
        analyses = await firestore_service.get_analyses({}, 1000)
        alerts = await firestore_service.get_unread_alerts(1000)
        logs = await firestore_service.get_investigation_logs(
            {"start_date": start_date, "end_date": end_date},
            1000
        )

        high_value_evidence = [e for e in evidence if e.get("relevance", 0) >= 0.7]
        critical_alerts = [a for a in alerts if a.get("severity") in ["high", "critical"]]
        completed_cycles = [l for l in logs if l.get("status") == "completed"]

        avg_relevance = 0
        if evidence:
            total_relevance = sum(e.get("relevance", 0) for e in evidence)
            avg_relevance = total_relevance / len(evidence)

        success_rate = 0
        if logs:
            success_rate = len(completed_cycles) / len(logs)

        statistics = {
            "period": {"start_date": start_date, "end_date": end_date},
            "totals": {
                "search_results": len(search_results),
                "evidence": len(evidence),
                "high_value_evidence": len(high_value_evidence),
                "analyses": len(analyses),
                "alerts": len(alerts),
                "critical_alerts": len(critical_alerts),
                "investigation_cycles": len(completed_cycles)
            },
            "average_relevance": avg_relevance,
            "success_rate": success_rate
        }

        return {"success": True, "data": statistics}
    except Exception as e:
        logger.error(f"Get statistics failed: {str(e)}")
        raise HTTPException(status_code=500, detail=str(e))

@router.post("/search/custom")
async def custom_search(request: CustomSearchRequest):
    try:
        if not request.queries:
            raise HTTPException(status_code=400, detail="Queries array is required")

        results = await investigation_service.perform_multi_source_search(request.queries)

        return {
            "success": True,
            "data": results,
            "count": len(results)
        }
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Custom search failed: {str(e)}")
        raise HTTPException(status_code=500, detail=str(e))
