from fastapi import Header, HTTPException
from typing import Optional
from config import settings

async def verify_api_key(
    x_api_key: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None)
):
    if not x_api_key and not authorization:
        raise HTTPException(
            status_code=401,
            detail="Authentication required. Provide X-API-Key header or Authorization bearer token"
        )

    if x_api_key:
        if not settings.API_KEYS or x_api_key in settings.API_KEYS:
            return {"type": "api_key", "validated": True}
        else:
            raise HTTPException(status_code=403, detail="Invalid API key")

    if authorization and authorization.startswith("Bearer "):
        token = authorization[7:]
        if not settings.API_KEYS or token in settings.API_KEYS:
            return {"type": "bearer", "validated": True}
        else:
            raise HTTPException(status_code=403, detail="Invalid bearer token")

    raise HTTPException(status_code=401, detail="Invalid authentication format")
