from apscheduler.schedulers.asyncio import AsyncIOScheduler
from apscheduler.triggers.interval import IntervalTrigger
from apscheduler.triggers.cron import CronTrigger
from datetime import datetime
from services.investigation_service import investigation_service
from services.firestore_service import firestore_service
from config import settings
from utils.logger import logger

scheduler = None

def start_continuous_research():
    global scheduler

    scheduler = AsyncIOScheduler(timezone="Europe/Budapest")

    interval_minutes = settings.SEARCH_INTERVAL_MINUTES

    scheduler.add_job(
        investigation_service.execute_full_investigation_cycle,
        trigger=IntervalTrigger(minutes=interval_minutes),
        id="investigation_cycle",
        name="Investigation Cycle",
        replace_existing=True,
        max_instances=1,
        coalesce=True
    )

    logger.info(f"Continuous research started with interval: {interval_minutes} minutes")

    scheduler.add_job(
        investigation_service.execute_full_investigation_cycle,
        trigger="date",
        run_date=datetime.now(),
        id="initial_investigation",
        name="Initial Investigation"
    )

    scheduler.add_job(
        deep_scan_job,
        trigger=CronTrigger(hour="*/6", timezone="Europe/Budapest"),
        id="deep_scan",
        name="Deep Scan",
        replace_existing=True
    )

    scheduler.start()
    logger.info("Scheduler started")

def stop_continuous_research():
    global scheduler
    if scheduler:
        scheduler.shutdown()
        scheduler = None
        logger.info("Continuous research stopped")

async def deep_scan_job():
    logger.info("Deep scan triggered")
    try:
        retention_days = settings.DATA_RETENTION_DAYS
        await firestore_service.clean_old_data("search_results", retention_days)
        await firestore_service.clean_old_data("investigation_logs", retention_days)
        logger.info("Deep scan completed")
    except Exception as e:
        logger.error(f"Deep scan failed: {str(e)}")
