    keywords = [
        "kollár", "sándor", "tek", "razzia", "szeged", "lencse", "balázs",
        "cédrus", "liget", "zoltán", "jogellenes", "fogvatartás",
        "visszaélés", "rendőrség", "balatonfűzfő", "gyermekpornográfia",
        "kábítószer", "csekély", "mennyiség", "házkutatás", "terrorelhárítás",
        "zombi", "ügy", "védőkirendelés", "europol", "stream", "zersetzung",
        "megfigyelés", "gps", "nyomkövetés", "behatolás", "anpr",
        "zaklatás", "ejeb", "helsinki", "tasz", "btk", "304", "305", "rtv"
    ]

    text = f"{result.get('title', '')} {result.get('text') or result.get('summary') or ''}".lower()

    relevance_score = 0.0
    matched_keywords = 0

    for keyword in keywords:
        if keyword in text:
            matched_keywords += 1
            relevance_score += 0.02

    published_date = result.get("published_date") or result.get("timestamp")
    if published_date:
        from datetime import datetime, timedelta
        try:
            date = datetime.fromisoformat(published_date.replace('Z', '+00:00'))
            days_since = (datetime.now() - date).days

            if days_since < 7:
                relevance_score += 0.2
            elif days_since < 30:
                relevance_score += 0.1
            elif days_since < 90:
                relevance_score += 0.05
        except:
            pass

    domain = result.get("domain", "")
    trust_domains = ["hvg.hu", "telex.hu", "444.hu", "index.hu", "birosag.hu", "police.hu"]
    if any(d in domain for d in trust_domains):
        relevance_score += 0.1

    return min(relevance_score, 1.0)
