```python
from celery_worker import celery_app
from services.investigation_service import investigation_service
from services.exa_service import exa_service
from services.xai_service import xai_service
from services.gemini_service import gemini_service
from services.parallel_service import parallel_service
from services.firestore_service import firestore_service
from utils.logger import logger
from typing import Dict, Any, List
import asyncio

def run_async(coro):
    loop = asyncio.get_event_loop()
    return loop.run_until_complete(coro)

@celery_app.task(name="tasks.full_investigation_cycle", bind=True, max_retries=3)
def full_investigation_cycle_task(self):
    try:
        logger.info(f"Celery task started: {self.request.id}")
        run_async(investigation_service.execute_full_investigation_cycle())
        logger.info(f"Celery task completed: {self.request.id}")
        return {"status": "success", "task_id": self.request.id}
    except Exception as e:
        logger.error(f"Celery task failed: {str(e)}")
        raise self.retry(exc=e, countdown=300)

@celery_app.task(name="tasks.search_query", bind=True)
def search_query_task(self, query: str, options: Dict[str, Any] = None):
    try:
        result = run_async(exa_service.search(query, options))
        return {"status": "success", "result": result}
    except Exception as e:
        logger.error(f"Search task failed: {str(e)}")
        raise

@celery_app.task(name="tasks.analyze_evidence", bind=True)
def analyze_evidence_task(self, evidence: Dict[str, Any], context: str):
    try:
        result = run_async(xai_service.analyze_evidence(evidence, context))
        return {"status": "success", "result": result}
    except Exception as e:
        logger.error(f"Analysis task failed: {str(e)}")
        raise

@celery_app.task(name="tasks.batch_analyze", bind=True)
def batch_analyze_task(self, results: List[Dict[str, Any]]):
    try:
        analyzed = []
        for result in results:
            analysis = run_async(xai_service.analyze_evidence(result, "Kollár Sándor ügy"))
            analyzed.append({**result, "analysis": analysis})
        return {"status": "success", "analyzed": analyzed}
    except Exception as e:
        logger.error(f"Batch analysis task failed: {str(e)}")
        raise

@celery_app.task(name="tasks.deep_scan", bind=True)
def deep_scan_task(self):
    try:
        run_async(firestore_service.clean_old_data("search_results", 365))
        run_async(firestore_service.clean_old_data("investigation_logs", 365))
        return {"status": "success"}
    except Exception as e:
        logger.error(f"Deep scan task failed: {str(e)}")
        raise

@celery_app.task(name="tasks.monitor_alerts", bind=True)
def monitor_alerts_task(self):
    try:
        alerts = run_async(firestore_service.get_unread_alerts(100))
        critical_alerts = [a for a in alerts if a.get("severity") in ["high", "critical"]]

        if critical_alerts:
            logger.warning(f"Found {len(critical_alerts)} critical alerts")

        return {
            "status": "success",
            "total_alerts": len(alerts),
            "critical_alerts": len(critical_alerts)
        }
    except Exception as e:
        logger.error(f"Monitor alerts task failed: {str(e)}")
        raise

@celery_app.task(name="tasks.generate_daily_report", bind=True)
def generate_daily_report_task(self):
    try:
        from datetime import datetime, timedelta

        end_date = datetime.now()
        start_date = end_date - timedelta(days=1)

        results = run_async(firestore_service.get_search_results({
            "start_date": start_date.isoformat(),
            "end_date": end_date.isoformat()
        }, 1000))

        evidence = run_async(firestore_service.get_evidence({}, 1000))

        report = run_async(xai_service.synthesize_findings(
            {"results": results, "evidence": evidence},
            "Napi összefoglaló jelentés készítése"
        ))

        run_async(firestore_service.save_analysis({
            "type": "daily_report",
            "report": report["content"],
            "date": datetime.now().isoformat()
        }))

        return {"status": "success", "date": datetime.now().isoformat()}
    except Exception as e:
        logger.error(f"Daily report task failed: {str(e)}")
        raise

@celery_app.task(name="tasks.check_new_sources", bind=True)
def check_new_sources_task(self, query: str):
    try:
        previous_results = run_async(firestore_service.get_search_results({"relevance_min": 0.5}, 100))

        new_content = run_async(exa_service.monitor_new_content(previous_results, query))

        if new_content:
            logger.info(f"Found {len(new_content)} new sources")
            for content in new_content:
                run_async(firestore_service.save_search_result(content))

        return {"status": "success", "new_sources": len(new_content)}
    except Exception as e:
        logger.error(f"Check new sources task failed: {str(e)}")
        raise

@celery_app.task(name="tasks.cross_reference_check", bind=True)
def cross_reference_check_task(self, entity_name: str):
    try:
        evidence = run_async(firestore_service.get_evidence({}, 500))

        related_evidence = [
            e for e in evidence
            if entity_name.lower() in str(e.get("content", "")).lower()
        ]

        if related_evidence:
            analysis = run_async(gemini_service.cross_reference_data(
                {"entity": entity_name},
                related_evidence,
                "entity_mentions"
            ))

            run_async(firestore_service.save_analysis({
                "type": "cross_reference",
                "entity": entity_name,
                "analysis": analysis
            }))

        return {
            "status": "success",
            "entity": entity_name,
            "related_count": len(related_evidence)
        }
    except Exception as e:
        logger.error(f"Cross reference task failed: {str(e)}")
