from redis import Redis
from redis.exceptions import RedisError
from config import settings
from utils.logger import logger
import json
from typing import Any, Optional
from datetime import timedelta

class CacheService:
    def __init__(self):
        self.redis_client = Redis(
            host=settings.REDIS_HOST,
            port=settings.REDIS_PORT,
            password=settings.REDIS_PASSWORD if settings.REDIS_PASSWORD else None,
            db=settings.REDIS_DB,
            decode_responses=True
        )

    def get(self, key: str) -> Optional[Any]:
        try:
            value = self.redis_client.get(key)
            if value:
                return json.loads(value)
            return None
        except RedisError as e:
            logger.error(f"Redis get error: {str(e)}")
            return None

    def set(self, key: str, value: Any, ttl: int = 3600):
        try:
            serialized = json.dumps(value, ensure_ascii=False)
            self.redis_client.setex(key, ttl, serialized)
        except RedisError as e:
            logger.error(f"Redis set error: {str(e)}")

    def delete(self, key: str):
        try:
            self.redis_client.delete(key)
        except RedisError as e:
            logger.error(f"Redis delete error: {str(e)}")

    def exists(self, key: str) -> bool:
        try:
            return self.redis_client.exists(key) > 0
        except RedisError as e:
            logger.error(f"Redis exists error: {str(e)}")
            return False

    def increment(self, key: str, amount: int = 1) -> int:
        try:
            return self.redis_client.incrby(key, amount)
        except RedisError as e:
            logger.error(f"Redis increment error: {str(e)}")
            return 0

    def set_with_ttl(self, key: str, value: Any, hours: int = 24):
        self.set(key, value, ttl=hours * 3600)

    def get_or_set(self, key: str, factory_func, ttl: int = 3600) -> Any:
        cached = self.get(key)
        if cached is not None:
            return cached

        value = factory_func()
        self.set(key, value, ttl)
        return value

    def clear_pattern(self, pattern: str):
        try:
            keys = self.redis_client.keys(pattern)
            if keys:
                self.redis_client.delete(*keys)
                logger.info(f"Cleared {len(keys)} keys matching pattern: {pattern}")
        except RedisError as e:
            logger.error(f"Redis clear pattern error: {str(e)}")

    def health_check(self) -> bool:
        try:
            return self.redis_client.ping()
        except RedisError:
            return False

cache_service = CacheService()
