from fastapi import Request, HTTPException
from fastapi.responses import JSONResponse
from typing import Callable
import time
from utils.cache_service import cache_service
from utils.logger import logger

async def rate_limit_middleware(request: Request, call_next: Callable):
    client_ip = request.client.host
    path = request.url.path

    if path in ["/health", "/", "/docs", "/openapi.json"]:
        return await call_next(request)

    rate_limit_key = f"rate_limit:{client_ip}:{path}"

    current_count = cache_service.get(rate_limit_key)

    if current_count is None:
        cache_service.set(rate_limit_key, 1, ttl=60)
        current_count = 1
    else:
        current_count = cache_service.increment(rate_limit_key)

    max_requests = 100

    if current_count > max_requests:
        logger.warning(f"Rate limit exceeded for {client_ip} on {path}")
        return JSONResponse(
            status_code=429,
            content={
                "error": "Too many requests",
                "message": "Rate limit exceeded. Please try again later."
            },
            headers={
                "Retry-After": "60"
            }
        )

    response = await call_next(request)
    response.headers["X-RateLimit-Limit"] = str(max_requests)
    response.headers["X-RateLimit-Remaining"] = str(max(0, max_requests - current_count))

    return response
