from prometheus_client import Counter, Histogram, Gauge, generate_latest, CONTENT_TYPE_LATEST
from fastapi import Response
import time
from functools import wraps
from utils.logger import logger

REQUEST_COUNT = Counter(
    "http_requests_total",
    "Total HTTP requests",
    ["method", "endpoint", "status"]
)

REQUEST_DURATION = Histogram(
    "http_request_duration_seconds",
    "HTTP request duration",
    ["method", "endpoint"]
)

INVESTIGATION_CYCLES = Counter(
    "investigation_cycles_total",
    "Total investigation cycles",
    ["status"]
)

SEARCH_QUERIES = Counter(
    "search_queries_total",
    "Total search queries",
    ["source"]
)

EVIDENCE_FOUND = Counter(
    "evidence_found_total",
    "Total evidence found",
    ["category"]
)

ALERTS_GENERATED = Counter(
    "alerts_generated_total",
    "Total alerts generated",
    ["severity"]
)

ACTIVE_INVESTIGATIONS = Gauge(
    "active_investigations",
    "Number of active investigations"
)

AI_API_CALLS = Counter(
    "ai_api_calls_total",
    "Total AI API calls",
    ["provider", "status"]
)

CACHE_HITS = Counter(
    "cache_hits_total",
    "Total cache hits"
)

CACHE_MISSES = Counter(
    "cache_misses_total",
    "Total cache misses"
)

def track_request(method: str, endpoint: str, status: int):
    REQUEST_COUNT.labels(method=method, endpoint=endpoint, status=status).inc()

def track_request_duration(method: str, endpoint: str, duration: float):
    REQUEST_DURATION.labels(method=method, endpoint=endpoint).observe(duration)

def track_investigation_cycle(status: str):
    INVESTIGATION_CYCLES.labels(status=status).inc()

def track_search_query(source: str):
    SEARCH_QUERIES.labels(source=source).inc()

def track_evidence(category: str):
    EVIDENCE_FOUND.labels(category=category).inc()

def track_alert(severity: str):
    ALERTS_GENERATED.labels(severity=severity).inc()

def track_ai_call(provider: str, status: str):
    AI_API_CALLS.labels(provider=provider, status=status).inc()

def track_cache_hit():
    CACHE_HITS.inc()

def track_cache_miss():
    CACHE_MISSES.inc()

def get_metrics():
    return Response(content=generate_latest(), media_type=CONTENT_TYPE_LATEST)

def metrics_decorator(func):
    @wraps(func)
    async def wrapper(*args, **kwargs):
        start_time = time.time()
        try:
            result = await func(*args, **kwargs)
            duration = time.time() - start_time
            track_request_duration(func.__name__, func.__module__, duration)
            return result
        except Exception as e:
            logger.error(f"Metrics decorator error: {str(e)}")
            raise
    return wrapper
