from datetime import datetime, timedelta
from typing import Dict, Any, List, Optional
from services.firestore_service import firestore_service
from services.xai_service import xai_service
from utils.logger import logger
import json

class ReportGenerator:

    async def generate_daily_report(self, date: Optional[datetime] = None) -> Dict[str, Any]:
        if date is None:
            date = datetime.now()

        start_date = date.replace(hour=0, minute=0, second=0, microsecond=0)
        end_date = start_date + timedelta(days=1)

        search_results = await firestore_service.get_search_results({
            "start_date": start_date.isoformat(),
            "end_date": end_date.isoformat()
        }, 10000)

        evidence = await firestore_service.get_evidence({}, 10000)
        daily_evidence = [
            e for e in evidence
            if self._is_from_date(e.get("created_at"), start_date)
        ]

        alerts = await firestore_service.get_unread_alerts(1000)
        daily_alerts = [
            a for a in alerts
            if self._is_from_date(a.get("created_at"), start_date)
        ]

        logs = await firestore_service.get_investigation_logs({
            "start_date": start_date.isoformat(),
            "end_date": end_date.isoformat()
        }, 1000)

        high_value_evidence = [e for e in daily_evidence if e.get("relevance", 0) >= 0.7]
        critical_alerts = [a for a in daily_alerts if a.get("severity") in ["high", "critical"]]

        summary = await xai_service.synthesize_findings(
            {
                "date": date.isoformat(),
                "search_results": len(search_results),
                "evidence_found": len(daily_evidence),
                "high_value_evidence": len(high_value_evidence),
                "alerts_generated": len(daily_alerts),
                "critical_alerts": len(critical_alerts),
                "investigation_cycles": len([l for l in logs if l.get("status") == "completed"])
            },
            f"Napi jelentés készítése {date.strftime('%Y-%m-%d')} napra"
        )

        report = {
            "date": date.isoformat(),
            "period": {
                "start": start_date.isoformat(),
                "end": end_date.isoformat()
            },
            "metrics": {
                "search_results": len(search_results),
                "evidence_found": len(daily_evidence),
                "high_value_evidence": len(high_value_evidence),
                "alerts_generated": len(daily_alerts),
                "critical_alerts": len(critical_alerts),
                "completed_cycles": len([l for l in logs if l.get("status") == "completed"]),
                "failed_cycles": len([l for l in logs if l.get("status") == "failed"])
            },
            "top_sources": self._get_top_sources(search_results),
            "key_findings": self._extract_key_findings(high_value_evidence),
            "critical_alerts": critical_alerts[:10],
            "summary": summary.get("content", ""),
            "generated_at": datetime.now().isoformat()
        }

        await firestore_service.save_analysis({
            "type": "daily_report",
            "date": date.isoformat(),
            "report": report
        })

        return report

    async def generate_weekly_report(self) -> Dict[str, Any]:
        end_date = datetime.now()
        start_date = end_date - timedelta(days=7)

        search_results = await firestore_service.get_search_results({
            "start_date": start_date.isoformat(),
            "end_date": end_date.isoformat()
        }, 10000)

        evidence = await firestore_service.get_evidence({}, 10000)
        weekly_evidence = [
            e for e in evidence
            if self._is_in_range(e.get("created_at"), start_date, end_date)
        ]

        analyses = await firestore_service.get_analyses({}, 1000)
        weekly_analyses = [
            a for a in analyses
            if self._is_in_range(a.get("created_at"), start_date, end_date)
        ]

        summary = await xai_service.synthesize_findings(
            {
                "period": "weekly",
                "results": search_results,
                "evidence": weekly_evidence,
                "analyses": weekly_analyses
            },
            f"Heti összefoglaló jelentés {start_date.strftime('%Y-%m-%d')} - {end_date.strftime('%Y-%m-%d')}"
        )

        report = {
            "period": {
                "start": start_date.isoformat(),
                "end": end_date.isoformat()
            },
            "metrics": {
                "total_searches": len(search_results),
                "evidence_collected": len(weekly_evidence),
                "analyses_performed": len(weekly_analyses),
                "average_relevance": sum(e.get("relevance", 0) for e in weekly_evidence) / len(weekly_evidence) if weekly_evidence else 0
            },
            "trends": self._analyze_trends(weekly_evidence),
            "top_entities": self._extract_top_entities(weekly_evidence),
            "summary": summary.get("content", ""),
            "generated_at": datetime.now().isoformat()
        }

        await firestore_service.save_analysis({
            "type": "weekly_report",
            "week_start": start_date.isoformat(),
            "report": report
        })

        return report

    async def generate_case_summary(self) -> Dict[str, Any]:
        all_evidence = await firestore_service.get_evidence({}, 10000)
        all_analyses = await firestore_service.get_analyses({}, 10000)
        all_alerts = await firestore_service.get_unread_alerts(10000)

        case_summary = await xai_service.synthesize_findings(
            {
                "evidence": all_evidence,
                "analyses": all_analyses,
                "alerts": all_alerts
            },
            "Teljes ügy átfogó összefoglalása minden rendelkezésre álló információval"
        )

        timeline = self._build_timeline(all_evidence)
        key_persons = self._extract_key_persons(all_evidence)
        key_organizations = self._extract_key_organizations(all_evidence)
        legal_references = self._extract_legal_references(all_evidence)

        summary = {
            "generated_at": datetime.now().isoformat(),
            "total_evidence": len(all_evidence),
            "total_analyses": len(all_analyses),
            "total_alerts": len(all_alerts),
            "case_summary": case_summary.get("content", ""),
            "timeline": timeline,
            "key_persons": key_persons,
            "key_organizations": key_organizations,
            "legal_references": legal_references
        }

        await firestore_service.save_analysis({
            "type": "case_summary",
            "summary": summary
        })

        return summary

    def _is_from_date(self, timestamp: Any, target_date: datetime) -> bool:
        if not timestamp:
            return False

        try:
            if hasattr(timestamp, 'timestamp'):
                ts = datetime.fromtimestamp(timestamp.timestamp())
            elif isinstance(timestamp, str):
                ts = datetime.fromisoformat(timestamp.replace('Z', '+00:00'))
            else:
                return False

            return ts.date() == target_date.date()
        except:
            return False

    def _is_in_range(self, timestamp: Any, start: datetime, end: datetime) -> bool:
        if not timestamp:
            return False

        try:
            if hasattr(timestamp, 'timestamp'):
                ts = datetime.fromtimestamp(timestamp.timestamp())
            elif isinstance(timestamp, str):
                ts = datetime.fromisoformat(timestamp.replace('Z', '+00:00'))
            else:
                return False

            return start <= ts <= end
        except:
            return False

    def _get_top_sources(self, results: List[Dict[str, Any]], limit: int = 10) -> List[Dict[str, Any]]:
        sources = {}
        for result in results:
            source = result.get("source", "unknown")
            if source not in sources:
                sources[source] = 0
            sources[source] += 1

        return [
            {"source": k, "count": v}
            for k, v in sorted(sources.items(), key=lambda x: x[1], reverse=True)[:limit]
        ]

    def _extract_key_findings(self, evidence: List[Dict[str, Any]], limit: int = 10) -> List[Dict[str, Any]]:
        sorted_evidence = sorted(evidence, key=lambda x: x.get("relevance", 0), reverse=True)
        return sorted_evidence[:limit]

    def _analyze_trends(self, evidence: List[Dict[str, Any]]) -> Dict[str, Any]:
        if not evidence:
            return {}

        by_date = {}
        for e in evidence:
            date_str = e.get("created_at", "")
            if date_str:
                date_key = date_str[:10] if isinstance(date_str, str) else str(date_str)[:10]
                if date_key not in by_date:
                    by_date[date_key] = []
                by_date[date_key].append(e)

        return {
            "daily_counts": {k: len(v) for k, v in by_date.items()},
            "trend_direction": "increasing" if len(by_date) > 1 else "stable"
        }

    def _extract_top_entities(self, evidence: List[Dict[str, Any]], limit: int = 20) -> Dict[str, List[str]]:
        persons = set()
        organizations = set()

        for e in evidence:
            entities = e.get("analysis", {}).get("entities", [])
            for entity in entities:
                if entity.get("category") == "PERSON":
                    persons.add(entity.get("entity"))
                elif entity.get("category") == "ORGANIZATION":
                    organizations.add(entity.get("entity"))

        return {
            "persons": list(persons)[:limit],
            "organizations": list(organizations)[:limit]
        }

    def _build_timeline(self, evidence: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        timeline = []
        for e in evidence:
            if e.get("created_at"):
                timeline.append({
                    "date": e.get("created_at"),
                    "type": e.get("type"),
                    "title": e.get("title"),
                    "relevance": e.get("relevance")
                })

        return sorted(timeline, key=lambda x: x.get("date", ""), reverse=True)[:50]

    def _extract_key_persons(self, evidence: List[Dict[str, Any]]) -> List[str]:
        return self._extract_top_entities(evidence, 50)["persons"]

    def _extract_key_organizations(self, evidence: List[Dict[str, Any]]) -> List[str]:
        return self._extract_top_entities(evidence, 50)["organizations"]

    def _extract_legal_references(self, evidence: List[Dict[str, Any]]) -> List[str]:
        references = set()
        for e in evidence:
            entities = e.get("analysis", {}).get("entities", [])
            for entity in entities:
                if entity.get("category") == "LEGAL_REFERENCE":
                    references.add(entity.get("entity"))
        return list(references)[:50]

report_generator = ReportGenerator()
