import smtplib
from email.mime.text import MIMEText
from email.mime.multipart import MIMEMultipart
from typing import List, Dict, Any
from config import settings
from utils.logger import logger
import os

class NotificationService:
    def __init__(self):
        self.smtp_server = os.getenv("SMTP_SERVER", "smtp.gmail.com")
        self.smtp_port = int(os.getenv("SMTP_PORT", "587"))
        self.smtp_username = os.getenv("SMTP_USERNAME", "")
        self.smtp_password = os.getenv("SMTP_PASSWORD", "")
        self.from_email = os.getenv("FROM_EMAIL", "")
        self.to_emails = os.getenv("TO_EMAILS", "").split(",")

    async def send_alert_email(self, alert: Dict[str, Any]):
        if not self.smtp_username or not self.to_emails[0]:
            logger.warning("Email notifications not configured")
            return

        try:
            subject = f"[ALERT] {alert.get('title', 'New Alert')}"

            body = f"""
            <html>
            <body>
                <h2>Kollár Investigation Alert</h2>
                <p><strong>Type:</strong> {alert.get('type')}</p>
                <p><strong>Severity:</strong> {alert.get('severity')}</p>
                <p><strong>Message:</strong> {alert.get('message')}</p>
                <p><strong>URL:</strong> {alert.get('url')}</p>
                <hr>
                <pre>{alert.get('metadata')}</pre>
            </body>
            </html>
            """

            msg = MIMEMultipart('alternative')
            msg['Subject'] = subject
            msg['From'] = self.from_email
            msg['To'] = ', '.join(self.to_emails)

            msg.attach(MIMEText(body, 'html'))

            with smtplib.SMTP(self.smtp_server, self.smtp_port) as server:
                server.starttls()
                server.login(self.smtp_username, self.smtp_password)
                server.send_message(msg)

            logger.info(f"Alert email sent to {len(self.to_emails)} recipients")

        except Exception as e:
            logger.error(f"Failed to send alert email: {str(e)}")

    async def send_daily_report_email(self, report: Dict[str, Any]):
        if not self.smtp_username or not self.to_emails[0]:
            logger.warning("Email notifications not configured")
            return

        try:
            subject = f"[REPORT] Daily Investigation Report - {report.get('date')}"

            body = f"""
            <html>
            <body>
                <h2>Kollár Investigation Daily Report</h2>
                <p><strong>Date:</strong> {report.get('date')}</p>

                <h3>Metrics</h3>
                <ul>
                    <li>Search Results: {report.get('metrics', {}).get('search_results', 0)}</li>
                    <li>Evidence Found: {report.get('metrics', {}).get('evidence_found', 0)}</li>
                    <li>High Value Evidence: {report.get('metrics', {}).get('high_value_evidence', 0)}</li>
                    <li>Critical Alerts: {report.get('metrics', {}).get('critical_alerts', 0)}</li>
                </ul>

                <h3>Summary</h3>
                <p>{report.get('summary', '')[:500]}...</p>

                <p>View Full Report</p>
            </body>
            </html>
            """

            msg = MIMEMultipart('alternative')
            msg['Subject'] = subject
            msg['From'] = self.from_email
            msg['To'] = ', '.join(self.to_emails)

            msg.attach(MIMEText(body, 'html'))

            with smtplib.SMTP(self.smtp_server, self.smtp_port) as server:
                server.starttls()
                server.login(self.smtp_username, self.smtp_password)
