                {"field_path": "status", "order": "ASCENDING"},
                {"field_path": "timestamp", "order": "DESCENDING"}
            ]
        }
    ]

    print(f"Total indexes to create: {len(indexes)}")
    print("Note: Indexes must be created manually in Firebase Console")
    print("Visit: ".format(settings.GCP_PROJECT_ID))

    for idx, index in enumerate(indexes, 1):
        print(f"\nIndex {idx}:")
        print(f"  Collection: {index['collection']}")
        print(f"  Fields:")
        for field in index['fields']:
            print(f"    - {field['field_path']}: {field['order']}")

if __name__ == "__main__":
    asyncio.run(create_indexes())
